import { supabase } from './client'
import type { Project, ProjectRole, ProjectStatus } from '@/entities/project/types'

type Row = {
  id: string
  tenant_id: string
  workplace_id: string | null
  owner_central_id: string
  title: string
  description: string | null
  color: string | null
  icon: string | null
  status: string
  is_favorite: boolean | null
  created_at: string
  updated_at: string
}

function mapRow(r: Row, role?: ProjectRole): Project {
  return {
    id: r.id,
    tenantId: r.tenant_id,
    workplaceId: r.workplace_id,
    ownerCentralId: r.owner_central_id,
    title: r.title,
    description: r.description,
    color: r.color,
    icon: r.icon,
    status: (r.status as ProjectStatus) ?? 'draft',
    isFavorite: r.is_favorite ?? false,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    roleForCurrentUser: role,
    objectivesCount: 0,
    membersCount: 0,
    fundBalance: 0,
    tags: [],
  }
}

export const projectsService = {
  /**
   * Lists projects in a workplace that the current user can see:
   * - projects they own (owner_central_id = centralUserId), OR
   * - projects they collaborate on (collaborators.object_type='project').
   * Returns each project with the user's effective role.
   */
  async listProjects(workplaceId: string, centralUserId: string): Promise<Project[]> {
    if (!workplaceId || !centralUserId) return []

    const { data: rows, error } = await supabase
      .from('projects')
      .select('*')
      .eq('workplace_id', workplaceId)
      .order('created_at', { ascending: false })
    if (error) throw error
    const list = (rows ?? []) as Row[]
    if (list.length === 0) return []

    const ids = list.map((r) => r.id)
    const { data: collabs } = await supabase
      .from('collaborators')
      .select('object_id, role')
      .eq('object_type', 'project')
      .eq('user_id', centralUserId)
      .in('object_id', ids)
    const collabRole = new Map<string, ProjectRole>()
    for (const c of (collabs ?? []) as { object_id: string; role: string }[]) {
      collabRole.set(c.object_id, (c.role as ProjectRole) ?? 'collaborator')
    }

    return list
      .map((r) => {
        const isOwner = r.owner_central_id === centralUserId
        const role: ProjectRole | undefined = isOwner
          ? 'owner'
          : collabRole.get(r.id)
        return role ? mapRow(r, role) : null
      })
      .filter((p): p is Project => p !== null)
  },

  async getProject(projectId: string): Promise<Project | null> {
    const { data, error } = await supabase
      .from('projects')
      .select('*')
      .eq('id', projectId)
      .maybeSingle()
    if (error || !data) return null
    return mapRow(data as Row)
  },

  async createProject(payload: {
    tenantId: string
    workplaceId: string
    ownerCentralId: string
    title: string
    description?: string
    color?: string
    icon?: string
    status?: ProjectStatus
  }): Promise<Project> {
    const { data, error } = await supabase
      .from('projects')
      .insert({
        tenant_id: payload.tenantId,
        workplace_id: payload.workplaceId,
        owner_central_id: payload.ownerCentralId,
        title: payload.title,
        description: payload.description ?? null,
        color: payload.color ?? null,
        icon: payload.icon ?? null,
        status: payload.status ?? 'active',
      })
      .select()
      .single()
    if (error) throw error
    return mapRow(data as Row, 'owner')
  },

  async updateProject(projectId: string, updates: Partial<Project>): Promise<void> {
    const patch: Record<string, unknown> = {}
    if (updates.title !== undefined) patch.title = updates.title
    if (updates.description !== undefined) patch.description = updates.description
    if (updates.color !== undefined) patch.color = updates.color
    if (updates.icon !== undefined) patch.icon = updates.icon
    if (updates.status !== undefined) patch.status = updates.status
    if (updates.isFavorite !== undefined) patch.is_favorite = updates.isFavorite
    const { error } = await supabase.from('projects').update(patch).eq('id', projectId)
    if (error) throw error
  },
}
